// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Resolves ball-vs-brick collisions: the deepest overlapping live brick is
// broken (scored once) and the ball is bounced off the face it hit and pushed
// back outside the brick, so it can never stick or plow through. The bounce
// axis is the one of least penetration (a corner hit, equal on both axes,
// flips vy). Previously this logic lived inside the render loop frame() and
// never deflected the ball at all (debt #2 / bug #1).
function resolveBricks(state) {
  const { ball, bricks } = state;
  while (true) {
    // The deepest overlap drives the bounce direction.
    let best = null;
    let bestDepth = 0;
    for (const brick of bricks) {
      if (!brick.alive || !collides(ball, brick)) continue;
      const depth = Math.min(
        ball.x + ball.r - brick.x,
        brick.x + brick.w - (ball.x - ball.r),
        ball.y + ball.r - brick.y,
        brick.y + brick.h - (ball.y - ball.r),
      );
      if (depth > bestDepth) {
        bestDepth = depth;
        best = brick;
      }
    }
    if (!best) break;

    best.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(best, state.combo);

    // Which face? The least penetration decides the axis.
    const overL = ball.x + ball.r - best.x;
    const overR = best.x + best.w - (ball.x - ball.r);
    const overT = ball.y + ball.r - best.y;
    const overB = best.y + best.h - (ball.y - ball.r);
    if (Math.min(overL, overR) < Math.min(overT, overB)) {
      ball.vx = overL <= overR ? -Math.abs(ball.vx) : Math.abs(ball.vx);
      ball.x = overL <= overR ? best.x - ball.r : best.x + best.w + ball.r;
    } else {
      ball.vy = overT <= overB ? -Math.abs(ball.vy) : Math.abs(ball.vy);
      ball.y = overT <= overB ? best.y - ball.r : best.y + best.h + ball.r;
    }
  }
}

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks (resolution moved here from frame()).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks
  resolveBricks(state);

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

