// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks (resolution moved here from frame()).
// Returns `true` if the ball is lost (exits through the bottom).
//
// The move is split into sub-steps capped at MAX_SUBSTEP pixels so that no
// single displacement can jump clean over an obstacle: a brick's crossing
// distance is BRICK_H + 2·BALL_R = 34, the paddle's is PADDLE_H + 2·BALL_R = 26,
// and 16 keeps every axis safely under both. Without this, a fast ball
// (ballSpeed(6) × 0.05 = 35.5) skipped straight through a brick.
export const MAX_SUBSTEP = 16;

export function step(state, dt) {
  const { ball, paddle } = state;

  const distance = Math.hypot(ball.vx, ball.vy) * dt;
  const substeps = Math.max(1, Math.ceil(distance / MAX_SUBSTEP));
  const h = dt / substeps;

  for (let i = 0; i < substeps; i++) {
    ball.x += ball.vx * h;
    ball.y += ball.vy * h;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0; // touching the paddle resets the combo
    }

    // Bricks
    resolveBricks(state);

    // Exit through the bottom: ball lost
    if (ball.y - ball.r > HEIGHT) {
      return true;
    }
  }
  return false;
}

