// Defect 3 — seam (double inversion) + collant: BRICK_GAP (8) is narrower
// than the ball's diameter (2·BALL_R = 14), so a ball descending centered on
// the gap overlaps BOTH bricks in one pass. It must break both, flip vy
// exactly once (two flips would cancel and the ball would sail through), and
// end up outside every remaining live brick.
test('brick: seam hit breaks both bricks with a single vy flip', () => {
  const state = createState(1);
  const a = state.bricks[0];
  const b = state.bricks[1];
  const gapCenter = a.x + a.w + BRICK_GAP / 2; // centered between the two bricks
  state.ball = {
    x: gapCenter, // straddling both bricks
    y: a.y - BALL_R - 1,
    r: BALL_R,
    vx: 0,
    vy: ballSpeed(1),
  };
  step(state, 1 / 60);
  assert.equal(a.alive, false, 'left brick must break');
  assert.equal(b.alive, false, 'right brick must break');
  assert.ok(state.ball.vy < 0, 'vy must be flipped exactly once (still pointing up)');
  assert.ok(state.ball.y + state.ball.r <= a.y, 'ball must end up above the row');
  for (const brick of state.bricks) {
    if (brick.alive) {
      assert.equal(collides(state.ball, brick), false, 'ball must be outside every live brick');
    }
  }
});

