// Defect 5 — paddle: the old window test compared the ball against
// `paddle.x + paddle.h` (12 px) instead of `paddle.x + paddle.w` (96 px), so
// the ball sailed straight through 84 px of paddle. The bounce must work
// across the full width.
test('paddle: bounce works across the full paddle width', () => {
  const state = createState(1);
  state.paddle.x = 200;
  state.ball = {
    x: 260, // well right of the 12 px zone the old test covered
    y: state.paddle.y - BALL_R - 1,
    r: BALL_R,
    vx: 0,
    vy: ballSpeed(1),
  };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0, 'ball must bounce up');
  assert.ok(state.ball.y + state.ball.r <= state.paddle.y, 'ball must exit above the paddle');
});

// Defect 5 — a fast descent (level 6: 35.5 px step at dt = 0.05) must not
// skip the 12 px paddle: crossing distance is PADDLE_H + 2·BALL_R = 26.
test('paddle: no tunneling at high speed', () => {
  const state = createState(6);
  state.paddle.x = 200;
  state.ball = {
    x: 230,
    y: state.paddle.y - BALL_R - 1,
    r: BALL_R,
    vx: 0,
    vy: ballSpeed(6),
  };
  step(state, 0.05);
  assert.ok(state.ball.vy < 0, 'ball must bounce, not pass through');
  assert.ok(state.ball.y + state.ball.r <= state.paddle.y, 'ball must exit above the paddle');
});

// Defect 5 — the mouse can teleport the paddle onto the ball: the ball must
// always leave through the paddle's top.
test('paddle: ball already overlapping the paddle (mouse teleport) exits upward', () => {
  const state = createState(1);
  state.paddle.x = 200;
  state.ball = {
    x: 248, // inside the paddle horizontally
    y: state.paddle.y + BALL_R, // center below the paddle's top edge
    r: BALL_R,
    vx: 0,
    vy: ballSpeed(1),
  };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0, 'ball must leave upward');
  assert.ok(state.ball.y + state.ball.r <= state.paddle.y, 'ball must be above the paddle');
});

