// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Resolves ball-vs-brick collisions: every live brick the ball overlaps is
// broken and scored exactly once, then the ball bounces off the deepest one
// and is pushed back outside, so it can never stick or plow through. At most
// one flip per axis per pass: two bricks sharing a seam must not cancel each
// other's bounce. Previously this logic lived inside the render loop frame()
// and never deflected the ball at all (debt #2 / bug #1).
//
// The bounce face is read from the position the ball occupied before this
// move (passed in as prevX/prevY): the face is the side the ball was fully
// outside of before the move. Entering through two faces at once is a corner.
// If the ball was already overlapping before the move (no entry face — spawn
// or teleport), the least penetration decides the axis, and equal
// penetrations mean a corner too.
function resolveBricks(state, prevX, prevY) {
  const { ball, bricks } = state;
  let flippedX = false;
  let flippedY = false;
  let guard = 0;
  let px = prevX;
  let py = prevY;

  while (guard++ <= bricks.length) {
    // The deepest overlap drives which brick to resolve against.
    let best = null;
    let bestDepth = 0;
    for (const brick of bricks) {
      if (!brick.alive || !collides(ball, brick)) continue;
      const depth = Math.min(
        ball.x + ball.r - brick.x,
        brick.x + brick.w - (ball.x - ball.r),
        ball.y + ball.r - brick.y,
        brick.y + brick.h - (ball.y - ball.r),
      );
      if (depth > bestDepth) {
        bestDepth = depth;
        best = brick;
      }
    }
    if (!best) break;

    // Break every live brick the ball still overlaps — each exactly once.
    for (const brick of bricks) {
      if (!brick.alive || !collides(ball, brick)) continue;
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }

    // Entry face, from the position the ball occupied before this move.
    const fromTop = py + ball.r <= best.y;
    const fromBottom = py - ball.r >= best.y + best.h;
    const fromLeft = px + ball.r <= best.x;
    const fromRight = px - ball.r >= best.x + best.w;
    const enteredVertical = fromTop || fromBottom;
    const enteredHorizontal = fromLeft || fromRight;

    if (enteredVertical && !enteredHorizontal) {
      if (!flippedY) {
        ball.vy = fromTop ? -Math.abs(ball.vy) : Math.abs(ball.vy);
        flippedY = true;
      }
      ball.y = fromTop ? best.y - ball.r : best.y + best.h + ball.r;
    } else if (enteredHorizontal && !enteredVertical) {
      if (!flippedX) {
        ball.vx = fromLeft ? -Math.abs(ball.vx) : Math.abs(ball.vx);
        flippedX = true;
      }
      ball.x = fromLeft ? best.x - ball.r : best.x + best.w + ball.r;
    } else if (enteredVertical && enteredHorizontal) {
      // Corner: entered through two faces at once — both components invert.
      if (!flippedX) {
        ball.vx = fromLeft ? -Math.abs(ball.vx) : Math.abs(ball.vx);
        flippedX = true;
      }
      if (!flippedY) {
        ball.vy = fromTop ? -Math.abs(ball.vy) : Math.abs(ball.vy);
        flippedY = true;
      }
      ball.x = fromLeft ? best.x - ball.r : best.x + best.w + ball.r;
      ball.y = fromTop ? best.y - ball.r : best.y + best.h + ball.r;
    } else {
      // No entry face (the ball was already overlapping before the move):
      // the least penetration decides the axis; equal (within float noise)
      // means a corner.
      const overL = ball.x + ball.r - best.x;
      const overR = best.x + best.w - (ball.x - ball.r);
      const overT = ball.y + ball.r - best.y;
      const overB = best.y + best.h - (ball.y - ball.r);
      const minX = Math.min(overL, overR);
      const minY = Math.min(overT, overB);
      // Below any real face distinction, above double-precision noise.
      const EPS = 1e-9;
      if (minX < minY - EPS) {
        if (!flippedX) {
          ball.vx = overL <= overR ? -Math.abs(ball.vx) : Math.abs(ball.vx);
          flippedX = true;
        }
        ball.x = overL <= overR ? best.x - ball.r : best.x + best.w + ball.r;
      } else if (minY < minX - EPS) {
        if (!flippedY) {
          ball.vy = overT <= overB ? -Math.abs(ball.vy) : Math.abs(ball.vy);
          flippedY = true;
        }
        ball.y = overT <= overB ? best.y - ball.r : best.y + best.h + ball.r;
      } else {
        // Equal penetrations: a corner — both components invert.
        if (!flippedX) {
          ball.vx = overL <= overR ? -Math.abs(ball.vx) : Math.abs(ball.vx);
          flippedX = true;
        }
        if (!flippedY) {
          ball.vy = overT <= overB ? -Math.abs(ball.vy) : Math.abs(ball.vy);
          flippedY = true;
        }
        ball.x = overL <= overR ? best.x - ball.r : best.x + best.w + ball.r;
        ball.y = overT <= overB ? best.y - ball.r : best.y + best.h + ball.r;
      }
    }

    // The push may have moved the ball: resolve the next overlap from the
    // position it now occupies.
    px = ball.x;
    py = ball.y;
  }
}

